// ─── CONFIGURE ────────────────────────────────────────────────
// Set ADMIN_TOKEN in n8n environment vars (same value as in 08-blog-auth)
// Set BLOG_PUBLISH_SECRET (same value as in main site .env.local)
// Set MAIN_SITE_URL  →  https://hotbotstudios.com
// ──────────────────────────────────────────────────────────────
const ADMIN_TOKEN         = $env.ADMIN_TOKEN         || 'hotbot-admin-token-2026';
const BLOG_PUBLISH_SECRET = $env.BLOG_PUBLISH_SECRET || 'hotbot-blog-secret-2026';
const MAIN_SITE_URL       = $env.MAIN_SITE_URL       || 'https://hotbotstudios.com';

const body = $input.first().json.body || $input.first().json;
const token              = (body.token || '').trim();
const post               = body.post  || {};
const writingInstructions = (body.writingInstructions || '').trim();

if (token !== ADMIN_TOKEN) {
  return [{ json: { valid: false, error: 'Invalid or expired session token. Please log in again.' } }];
}

if (!post.title || !post.slug) {
  return [{ json: { valid: false, error: 'Post must have a title and slug.' } }];
}

// Build the Claude prompt
const hasContent = (post.content || '').trim().length > 100;
const claudePrompt = hasContent
  ? `You are a professional content editor and SEO expert for HotBot Studios, a US-based AI automation and digital marketing agency.

Your job is to enhance the following blog post for publication. Improve:
1. Writing quality, clarity, and flow
2. SEO — naturally integrate the post's keywords, improve headings (H2/H3), ensure keyword density is appropriate
3. Structure — ensure proper HTML heading hierarchy (h2, h3), paragraph breaks, and bullet lists where appropriate
4. Add a compelling intro paragraph if it feels weak
5. Ensure the tone is authoritative, expert, and engaging for a US business audience
6. Keep all the existing key facts and information
7. Ensure the conclusion encourages the reader to engage with HotBot Studios

Post title: ${post.title}
Post category: ${post.category || 'General'}
Post tags: ${(post.tags || []).join(', ')}

Return ONLY the enhanced HTML content (no markdown, no code blocks, just the HTML body content). Start directly with the first <p> or <h2> tag.

Original content:
${post.content}`
  : `You are a professional blog writer and SEO expert for HotBot Studios, a US-based AI automation and digital marketing agency.

Write a high-quality, SEO-optimized blog post in HTML format with the following specifications:

Title: ${post.title}
Category: ${post.category || 'General'}
Tags/Keywords: ${(post.tags || []).join(', ')}
Excerpt (topic summary): ${post.excerpt || post.title}

Writing instructions from the editor:
${writingInstructions || 'Write an expert, engaging post of 1000-1500 words targeting US business owners and marketers. Include real insights, specific tips, and practical advice. Position HotBot Studios as the expert solution provider throughout.'}

SEO requirements:
- Use the post title keywords naturally throughout
- Include 2-4 H2 subheadings with relevant keywords
- Use bullet/numbered lists where appropriate
- Write a strong intro paragraph that hooks the reader
- End with a clear call-to-action encouraging readers to work with HotBot Studios
- Target US business owners as the primary audience
- Professional, authoritative tone

Return ONLY the HTML content (no markdown, no code blocks, no <!DOCTYPE>). Use only: <p>, <h2>, <h3>, <ul>, <ol>, <li>, <strong>, <em> tags. Start directly with the first <p> tag.`;

return [{
  json: {
    valid: true,
    post,
    claudePrompt,
    hasContent,
    publishSecret: BLOG_PUBLISH_SECRET,
    publishUrl: MAIN_SITE_URL + '/api/blog/publish',
    siteUrl: MAIN_SITE_URL
  }
}];

const claudeResponse = $input.first().json;
const previousData    = $('IF — Token Valid?').first().json;

// Extract text from Claude's response structure
let generatedContent = '';
if (claudeResponse.content && Array.isArray(claudeResponse.content)) {
  generatedContent = claudeResponse.content
    .filter((block) => block.type === 'text')
    .map((block) => block.text)
    .join('')
    .trim();
} else if (typeof claudeResponse.content === 'string') {
  generatedContent = claudeResponse.content.trim();
}

if (!generatedContent) {
  throw new Error('Claude returned empty content. Check the API key and prompt.');
}

const post = previousData.post;

// Calculate read time (avg 200 words/min)
const wordCount = generatedContent.replace(/<[^>]+>/g, ' ').split(/\s+/).filter(Boolean).length;
const readMinutes = Math.max(3, Math.round(wordCount / 200));

const now = new Date().toISOString();

const finalPost = {
  id:          post.id || String(Date.now()),
  slug:        post.slug,
  title:       post.title,
  excerpt:     post.excerpt || generatedContent.replace(/<[^>]+>/g, ' ').slice(0, 200).trim() + '...',
  content:     generatedContent,
  category:    post.category || 'General',
  adTopic:     post.adTopic || 'general',
  tags:        Array.isArray(post.tags) ? post.tags : [],
  author:      post.author || 'HotBot Studios',
  publishedAt: post.publishedAt || now,
  updatedAt:   now,
  status:      post.status || 'published',
  readTime:    readMinutes + ' min read',
};

return [{
  json: {
    finalPost,
    publishSecret: previousData.publishSecret,
    publishUrl:    previousData.publishUrl,
    siteUrl:       previousData.siteUrl,
  }
}];

